<script setup lang="ts">
import { ref } from 'vue';
import { Users, Settings2, X } from 'lucide-vue-next';
import { useApp } from '../store';
import { useDialogFocus } from '../useDialogFocus';
import type { Permissions, PermissionKey } from '@music-share/shared';
const app=useApp(),emit=defineEmits<{close:[]}>(),panel=ref<'members'|'settings'>('members'),dialog=ref<HTMLElement|null>(null);
useDialogFocus(dialog,()=>emit('close'));
const keys:PermissionKey[]=['skip','seek','enqueue'];const labels:Record<PermissionKey,string>={skip:'切歌 / 播放控制',stream:'旧版兼容字段',seek:'进度切换',enqueue:'加入播放列表'};
function setDefault(key:PermissionKey,value:boolean){if(app.room)void app.act({type:'defaults',payload:{...app.room.defaults,[key]:value}});}
function setOverride(memberId:string,key:PermissionKey,value:string){const member=app.room?.members.find(m=>m.id===memberId);if(!member)return;const overrides:Partial<Permissions>={...member.overrides};if(value==='default')delete overrides[key];else overrides[key]=value==='allow';void app.act({type:'permission',payload:{memberId,overrides}});}
</script>
<template><Teleport to="body"><div class="modal-backdrop tone-modal-backdrop" @click.self="emit('close')"><section ref="dialog" class="tone-dialog members-dialog" role="dialog" aria-modal="true" aria-label="房间成员与权限"><header class="dialog-heading"><h2>一起听的人</h2><button class="round-close" aria-label="关闭成员与权限" @click="emit('close')"><X :size="20" /></button></header><div class="tabs"><button :class="{active:panel==='members'}" @click="panel='members'"><Users :size="16" />成员</button><button :class="{active:panel==='settings'}" @click="panel='settings'"><Settings2 :size="16" />权限</button></div><template v-if="panel==='members'"><div v-for="member in app.room?.members" :key="member.id" class="member-row"><span class="portrait">{{ member.name.slice(0,1) }}</span><span>{{ member.name }}<small>{{ member.id===app.room?.hostId?'房主':member.online?'在线收听':'暂时离线' }}</small></span><i class="dot" :class="{online:member.online}" /></div><p class="aside-note">本地音量只影响自己。切歌与进度由房间统一同步。</p></template><template v-else><h3>房间默认权限</h3><label v-for="key in keys" :key="key" class="permission-row"><span>{{ labels[key] }}</span><input type="checkbox" :checked="app.room?.defaults[key]" :disabled="!app.host||!app.connected" @change="setDefault(key,($event.target as HTMLInputElement).checked)" /></label><template v-if="app.host"><h3>成员单独设置</h3><div v-for="member in app.room?.members.filter(m=>m.id!==app.room?.hostId)" :key="member.id" class="override-card"><strong>{{ member.name }}</strong><label v-for="key in keys" :key="key" class="override-row"><span>{{ labels[key] }}</span><select class="tone-select" :value="member.overrides[key]===undefined?'default':member.overrides[key]?'allow':'deny'" :disabled="!app.connected" @change="setOverride(member.id,key,($event.target as HTMLSelectElement).value)"><option value="default">跟随房间</option><option value="allow">允许</option><option value="deny">禁止</option></select></label></div></template></template></section></div></Teleport></template>
